package webui

// stylesDashboard is the overview page: head, trust badge, ops stats, workspace panels, fleet overview and recent tasks.
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesDashboard = `.dashboard-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:16px}.dashboard-head h2{margin:3px 0;font-size:22px}.dashboard-head>div>p:last-child{color:var(--muted);font-size:11px}.trust-badge{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:15px;background:var(--green-soft);color:var(--green);font-size:10px;font-weight:700}.ops-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.ops-stats>a{min-height:104px;display:grid;grid-template-columns:44px 1fr;align-items:center;gap:13px;padding:18px 16px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:var(--shadow)}.ops-stats>a:hover{transform:translateY(-2px);border-color:var(--accent);box-shadow:var(--shadow-lift)}.ops-stats>a:active{transform:translateY(0);box-shadow:var(--shadow)}.stat-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:11px;background:var(--surface-3)}.stat-icon svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.8}.stat-icon.green{background:var(--green-soft);color:var(--green)}.stat-icon.blue{background:var(--blue-soft);color:var(--blue)}.stat-icon.amber{background:var(--amber-soft);color:var(--amber)}.stat-icon.red{background:var(--red-soft);color:var(--red)}.ops-stats small,.ops-stats strong,.ops-stats p{display:block}.ops-stats small,.ops-stats p{color:var(--muted);font-size:10px}.ops-stats strong{font-size:26px;line-height:1.05;font-weight:820;letter-spacing:-.01em}.ops-stats strong em{color:var(--muted);font-size:11px;font-style:normal;font-weight:700}.dashboard-columns{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:12px;margin-top:12px}.workspace-panel{border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.workspace-panel>header{min-height:66px;display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid var(--line)}.workspace-panel h3{margin-top:2px;font-size:16px}.workspace-panel>header>a{color:var(--accent);font-size:10px;font-weight:700}.fleet-overview-list>a{min-height:64px;display:grid;grid-template-columns:38px minmax(0,1fr) auto 90px 12px;align-items:center;gap:10px;padding:9px 14px;border-bottom:1px solid var(--line)}.fleet-overview-list>a:last-child{border-bottom:0}.fleet-overview-list>a:hover{position:relative}.fleet-overview-list>a:hover::before{content:"";position:absolute;left:0;top:9px;bottom:9px;width:3px;border-radius:3px;background:var(--accent)}.node-avatar,.machine-avatar{display:grid;place-items:center;border-radius:9px;background:var(--accent-soft);color:var(--accent);font-weight:800}.node-avatar{width:36px;height:36px}.fleet-overview-list strong,.fleet-overview-list small{display:block}.fleet-overview-list strong{font-size:11px}.fleet-overview-list small,.fleet-overview-list time{color:var(--muted);font-size:10px}.fleet-overview-list>a>i{color:var(--accent);font-style:normal}.recent-tasks>div>a{min-height:58px;display:grid;grid-template-columns:10px minmax(0,1fr) 70px 12px;align-items:center;gap:9px;padding:9px 14px;border-bottom:1px solid var(--line)}.recent-tasks>div>a:last-child{border-bottom:0}.recent-tasks>div>a:hover{position:relative}.recent-tasks>div>a:hover::before{content:"";position:absolute;left:0;top:9px;bottom:9px;width:3px;border-radius:3px;background:var(--accent)}.recent-tasks strong,.recent-tasks small{display:block}.recent-tasks strong{font-size:11px}.recent-tasks small,.recent-tasks time{color:var(--muted);font-size:10px}.recent-tasks b{color:var(--accent)}
`
